    a, b = readList(), readList()

    idx = sorted([i for i in range(n)], key=lambda x: b[x])
    while idx and b[idx[-1]] >= p:
        idx.pop()

    cost, curr = p, n - 1
    for i in idx:
        if not curr:
            [MASK]
