```python
def get_animal_characteristics(i):
    """
    Returns the characteristics of the i-th animal in the list, recursively parsing nested dictionaries.
    If i is out of bounds, returns None.

    :param i: Index of the animal in the list.
    :return: Dictionary of characteristics or None if index is out of bounds.
    """
    def parse_characteristics(characteristics):
        result = {}
        for key, value in characteristics.items():
            if isinstance(value, dict):
                result[key] = parse_characteristics(value)
            else:
                result[key] = value
        return result

    animals = [
        {
            "name": "Lion",
            "carnivore": True,
            "attributes": {
                "fur": True,
                "tail": True,
                "size": "large"
            }
        },
        {
            "name": "Fish",
            "carnivore": False,
            "attributes": {
                "scales": True,
                "fins": True
            }
        },
        {
            "name": "Eagle",
            "carnivore": True,
            "attributes": {
                "feathers": True,
                "wings": True,
                "diet": {
                    "carnivore": True,
                    "vegetarian": False
                }
            }
        }
    ]

[MASK]

    animal = animals[i]
    return {key: parse_characteristics(value) if isinstance(value, dict) else value for key, value in animal.items()}
