def test_basic_case():
    assert abs(trimmean_optimized([2, 8, 10, 17, 23, 50], 20) - 14.5) < 1e-5

def test_no_outliers():
    assert abs(trimmean_optimized([4, 4, 4, 4, 4, 4, 4], 10) - 4.0) < 1e-5

def test_all_identical_elements():
    assert abs(trimmean_optimized([10, 10, 10, 10, 10], 10) - 10.0) < 1e-5

def test_minimum_trim():
    assert abs(trimmean_optimized([1, 2, 3], 0) - 2.0) < 1e-5

def test_maximum_trim():
    assert abs(trimmean_optimized([1, 2, 3, 4, 5], 40) - 3.0) < 1e-5 # Here, 1 and 5 are trimmed

def test_large_array():
    large_array = list(range(1000))
    assert abs(trimmean_optimized(large_array, 10) - 499.5) < 1e-1

def test_edge_cases():
    # Edge case: return 0 if per is exactly 0
    assert trimmean_optimized([1, 2, 3], 0) == 2.0

    # Edge case: single trim
    assert abs(trimmean_optimized([10, 20, 30], 33.3333) - 20.0) < 1e-5 # Only middle element remains

def test_invalid_percentage():
    # Test for invalid percentage values
    try:
        trimmean_optimized([1, 2, 3], -10)
        assert False, "Expected ValueError for negative percentage"
    except ValueError:
        assert True

    try:
        trimmean_optimized([1, 2, 3], 50)
        assert False, "Expected ValueError for percentage of 50 or higher"
    except ValueError:
        assert True

test_basic_case()
