def assign_html_tags(font_counts, styles):
    """
    Assigns HTML tags to font sizes based on their frequency in the document.

    :param font_counts: List of tuples (font_size, count).
    :param styles: Dictionary with font sizes as keys and style information as values.
    :return: Dictionary mapping font sizes to HTML tags.
    """
    font_size_dict = {}
    for font_size, count in font_counts:
        if font_size in font_size_dict:
            font_size_dict[font_size] += count
        else:
            font_size_dict[font_size] = count

    sorted_font_sizes = []
    for font_size, _ in font_counts:
        if font_size not in sorted_font_sizes:
            inserted = False
            for i in range(len(sorted_font_sizes)):
                if font_size_dict[font_size] > font_size_dict[sorted_font_sizes[i]]:
                    sorted_font_sizes.insert(i, font_size)
                    inserted = True
                    break
            if not inserted:
                sorted_font_sizes.append(font_size)

    html_tags = {1: 'h1', 2: 'h2', 3: 'h3', 4: 'h4', 5: 'h5', 6: 'h6'}
    font_to_tag = {}
[MASK]
    return font_to_tag
