def test_simple_function():
    source_code = '''def foo():\n    return 42\n'''
    assert tokenize_python_script(source_code) == [
        'def', 'foo', '(', ')', ':', 'NEWLINE', 'return', '42', 'NEWLINE'
    ]

def test_function_with_string():
    source_code = '''def foo():\n    return "Hello, World!"\n'''
    assert tokenize_python_script(source_code) == [
        'def', 'foo', '(', ')', ':', 'NEWLINE', 'return', '"Hello, World!"', 'NEWLINE'
    ]

def test_multiline_string():
    source_code = '''def foo():\n    """This is a docstring."""\n    return 42\n'''
    assert tokenize_python_script(source_code) == [
        'def', 'foo', '(', ')', ':', 'NEWLINE', '"""This is a docstring."""', 'NEWLINE', 'return', '42', 'NEWLINE'
    ]

def test_comments():
    source_code = '''# This is a comment\ndef foo():\n    return 42\n'''
    assert tokenize_python_script(source_code) == [
        '# This is a comment', 'NEWLINE', 'def', 'foo', '(', ')', ':', 'NEWLINE', 'return', '42', 'NEWLINE'
    ]

def test_indentation_and_whitespace():
    source_code = '''  \ndef foo():\n    return 42\n  \n'''
    assert tokenize_python_script(source_code) == [
        'NEWLINE', 'def', 'foo', '(', ')', ':', 'NEWLINE', 'return', '42', 'NEWLINE', 'NEWLINE'
    ]

def test_keywords_and_operators():
    source_code = '''if x == 42:\n    return True\n'''
    assert tokenize_python_script(source_code) == [
        'if', 'x', '==', '42', ':', 'NEWLINE', 'return', 'True', 'NEWLINE'
    ]

test_simple_function()
test_function_with_string()
test_multiline_string()
test_comments()
test_indentation_and_whitespace()
test_keywords_and_operators()

