Note:
- You may assume the tree has no duplicate nodes.
- The array does not have to be sorted.

```python
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_into_bst(root, value):
    if root is None:
        return TreeNode(value)
    if value < root.value:
        root.left = insert_into_bst(root.left, value)
    else:
        root.right = insert_into_bst(root.right, value)
    return root

def build_bst(arr):
    if not arr:
        return None
    root = TreeNode(arr[0])
    for value in arr[1:]:
        insert_into_bst(root, value)
    return root

def sum_at_k_distance(root, k):
    if root is None:
        return 0
    if k == 0:
