def generate_vnf_threshold_config(network_location):
    """
    Generate a fake VNF (Virtual Network Function) performance metric threshold configuration.

    :param network_location: str, represents the current network location.
    :return: dict, VNF threshold configuration with dynamically resolved callbackUri.
    """
    base_config = {
        "vnf_id": "4f3b8e2c-1d5e-4f2f-9736-382a265d5d56",
        "performance_metrics": {
