def find_arithmetic_progression(n: int, arr: List[int]) -> Union[List[int], int]:
    """ Given a sequence of integers, find four distinct indices such that the elements at those indices form an arithmetic progression.
    If such a sequence is found, output the four indices in any order. If there is no such sequence, output `-1`.

    >>> find_arithmetic_progression(6, [3, 5, 7, 9, 11, 13])
    [2, 3, 4, 5]
    >>> find_arithmetic_progression(5, [1, 2, 4, 7, 11])
    -1
    """

```python
def find_arithmetic_progression(n, arr):
[MASK]

    idx_map = defaultdict(list)
    for i in range(n):
        idx_map[arr[i]].append(i + 1)

    # Check for directly confirmed indexes with at least 4 same values
    for key in idx_map:
        if len(idx_map[key]) >= 4:
            return idx_map[key][:4]

    # Check for combinations that make an arithmetic progression
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                diff1 = arr[j] - arr[i]
                diff2 = arr[k] - arr[j]
                common_diff = diff2
                target = arr[k] + common_diff
                if target in idx_map:
                    for l in idx_map[target]:
                        curr_idx = [i + 1, j + 1, k + 1, l]
                        distinct_flags = set(curr_idx)
                        if len(distinct_flags) == 4:
                            return curr_idx

    return -1
```

