def generate_optimal_bounds(dates, default_bounds, custom_bounds):
    """
    Generates optimal bounds for a portfolio optimization problem.

    Parameters:
    dates (list): A list of dates.
    default_bounds (dict): A dictionary with keys 'lower' and 'upper' representing default bounds.
    custom_bounds (dict): A dictionary with dates as keys and dictionaries of custom bounds for stocks as values.

    Returns:
    dict: A dictionary with dates as keys and dictionaries of stock bounds as values.
    """
[MASK]

    result = {}
    all_stocks = set()

    for stock_bounds in custom_bounds.values():
        all_stocks.update(stock_bounds.keys())

    for date in dates:
        result[date] = {stock: [default_lower, default_upper] for stock in all_stocks}

        if date in custom_bounds:
            for stock, bounds in custom_bounds[date].items():
                result[date][stock] = bounds

        total_upper = sum(upper for lower, upper in result[date].values())
        if total_upper > 1:
            for stock in result[date]:
                lower, upper = result[date][stock]
                result[date][stock][1] = upper * (1 / total_upper)

    return result
```

